export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task gets [x] prefix', () => {
  assert.equal(taskLabel('draft', true), '[x] draft');
  assert.equal(taskLabel('submit review', true), '[x] submit review');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('draft', false), '[ ] draft');
  assert.equal(taskLabel('submit review', false), '[ ] submit review');
});

test('preserves supplied name exactly', () => {
  assert.equal(taskLabel('  padded task  ', true), '[x]   padded task  ');
  assert.equal(taskLabel('  padded task  ', false), '[ ]   padded task  ');
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('Task #123: [x] nested', true), '[x] Task #123: [x] nested');
});

